mapper.sql:
SELECT ROW_NUMBER() OVER(ORDER BY emp31_officer_yn DESC, emp31_init_assign_date, emp31_pos_cd, emp31_person_nm) AS emp31_director_id , t.* FROM ( SELECT emp01_person_id AS emp31_person_id , f_emp_kor_nm(emp01_person_id) AS emp31_person_nm , emp02_chn_nm AS emp31_chn_nm , f_get_emptrans(emp01_person_id, f_sysdate()::date, 'pos_cd') AS emp31_pos_cd , f_get_emptrans(emp01_person_id, f_sysdate()::date, 'pos_nm') AS emp31_pos_nm , COALESCE(SUBSTRING(to_decrypts(emp02_ctz_no), 1, 6), '미입력') AS emp31_ctz_no , COALESCE(emp03_officer_yn, 'false') AS emp31_officer_yn , emp03_non_stay_yn AS emp31_non_stay_yn , emp03_duty AS emp31_duty , emp31_init_assign_date , emp31_rcnt_assing_date , emp31_expire_date , emp31_assign_cnt , emp31_add_title , emp31_prefer_stock , emp31_common_stock , emp31_note , COALESCE(emp31_qualified, ' ') AS emp31_qualified , AS emp31_career , emp31_end_date , emp31_end_reason
WHERE emp01_company_id = #{companyId}
) t ORDER BY emp31_pos_cd

mapper.delete:
DELETE FROM sys99_print
 WHERE sys99_company_id      = #{companyId}
   AND sys99_person_id       = #{personId}
   AND sys99_window_class_nm LIKE #{windowClassName}

mapper.insert:
INSERT INTO sys99_print ( sys99_print_id, sys99_company_id, sys99_person_id, sys99_window_class_nm, sys99_group_id , sys99_string01, sys99_string02, sys99_string03, sys99_string04 , sys99_date01, sys99_date02, sys99_date03, sys99_long01 , sys99_string05, sys99_string06, sys99_string07, sys99_string08, sys99_string09, sys99_string10, sys99_string11 , sys99_date04, sys99_string12, sys99_text01, sys99_text02 ) SELECT f_create_seq(), #{companyId}, #{personId}, #{windowClassName}, #{groupId} , COALESCE(r.emp31_pos_nm, ''), COALESCE(r.emp31_person_nm, ''), COALESCE(r.emp31_chn_nm, ''), COALESCE(r.emp31_ctz_no, '') , r.emp31_init_assign_date, r.emp31_rcnt_assing_date, r.emp31_expire_date, COALESCE(r.emp31_assign_cnt, 0) , COALESCE(r.emp31_add_title, ''), COALESCE(r.emp31_qualified, ''), COALESCE(r.emp31_career, ''), COALESCE(r.emp31_note, '') , CASE WHEN r.emp31_officer_yn = 'true' THEN '등기' ELSE '비등기' END , CASE WHEN r.emp31_non_stay_yn IS NULL OR r.emp31_non_stay_yn != 'true' THEN '상임' ELSE '비상임' END , COALESCE(r.emp31_duty, '') , r.emp31_end_date, COALESCE(r.emp31_end_reason, ''), COALESCE(r.emp31_task_nm, ''), COALESCE(r.emp31_task_detail, '') FROM ( SELECT ROW_NUMBER() OVER(ORDER BY emp31_officer_yn DESC, emp31_init_assign_date, emp31_pos_cd, emp31_person_nm) AS emp31_director_id , t.* FROM ( SELECT emp01_person_id AS emp31_person_id , f_emp_kor_nm(emp01_person_id) AS emp31_person_nm , emp02_chn_nm AS emp31_chn_nm , f_get_emptrans(emp01_person_id, f_sysdate()::date, 'pos_cd') AS emp31_pos_cd , f_get_emptrans(emp01_person_id, f_sysdate()::date, 'pos_nm') AS emp31_pos_nm , COALESCE(SUBSTRING(to_decrypts(emp02_ctz_no), 1, 6), '미입력') AS emp31_ctz_no , COALESCE(emp03_officer_yn, 'false') AS emp31_officer_yn , emp03_non_stay_yn AS emp31_non_stay_yn , emp03_duty AS emp31_duty , emp31_init_assign_date , emp31_rcnt_assing_date , emp31_expire_date , emp31_assign_cnt , emp31_add_title , emp31_prefer_stock , emp31_common_stock , emp31_note , emp31_qualified , AS emp31_career , emp31_end_date , emp31_end_reason , tdm35_task_nm AS emp31_task_nm , tdm35_task_detail AS emp31_task_detail
LEFT OUTER JOIN (SELECT DISTINCT tdm35_task_relate_detail_id , tdm35_task_nm COLLATE "ko_KR.utf8" AS tdm35_task_nm , tdm12_content AS tdm35_task_detail , tdm30_person_id AS tdm35_person_id FROM getTdm30RoleAllc(#{companyId}, f_sysdate()::date, true) INNER JOIN tdm34_role_allc_detail ON tdm30_role_allc_id = tdm34_role_allc_id INNER JOIN tdm35_role_allc_task ON tdm35_role_allc_detail_id = tdm34_role_allc_detail_id INNER JOIN tdm12_task_relate_detail ON tdm35_task_relate_detail_id = tdm12_task_relate_detail_id ORDER BY tdm35_task_nm) task ON tdm35_person_id = emp01_person_id WHERE emp01_company_id = #{companyId} AND emp01_person_id IN #{pid}
) t ORDER BY emp31_pos_cd ) r
